commands:
set -euo pipefail
EXPECTED=3d3a38885fb458d7693eab39450dad8506d504f6
test "$(git rev-parse HEAD)" = "$EXPECTED"
ROOT=managed_components/espressif__esp-zigbee-lib/include
python3 - <<'PY'
from pathlib import Path
root=Path('managed_components/espressif__esp-zigbee-lib/include')
needles=('status_change_notif','ZONE_STATUS_CHANGE','zone_status_change','ias_zone_status')
for p in sorted(root.rglob('*')):
    if not p.is_file(): continue
    try: lines=p.read_text(errors='ignore').splitlines()
    except Exception: continue
    hits=[]
    for i,l in enumerate(lines):
        if any(n.lower() in l.lower() for n in needles): hits.append(i)
    if not hits: continue
    print('===',p,'===')
    spans=[]
    for i in hits:
        a=max(0,i-12); b=min(len(lines),i+22)
        if spans and a<=spans[-1][1]: spans[-1]=(spans[-1][0],max(spans[-1][1],b))
        else: spans.append((a,b))
    for a,b in spans:
        for n in range(a,b): print(f'{n+1:4d}: {lines[n]}')
        print()
PY
echo '=== exported IAS-related functions ==='
grep -RnhE '^[a-zA-Z_][a-zA-Z0-9_ *]+ezb_[a-zA-Z0-9_]*(ias|zone)[a-zA-Z0-9_]*\(' "$ROOT" 2>/dev/null | sort -u || true
echo '=== ESP native IAS symbols too ==='
grep -RniE -B8 -A20 'esp_zb.*ias.*zone|ias.*zone.*status.*change|zone.*status.*change.*cmd' managed_components/espressif__esp-zigbee-lib/include 2>/dev/null || true
